/* The HST back channel's tables (modem/hst_tabs, generated by
 * tools/gen_hst_tabs.py) and its 8-DPSK transmitter (modem/hst_back.c);
 * docs/history/hst-facts.md, "Back channel".
 *
 *   steps        hst_bstep is BF §3's row, and the firmware's 0x43705261
 *                read a nibble at a time from the low end
 *   scr17        1 + x^-14 + x^-17 without V.22bis's 64-ones rule: 64 ones
 *                on the line pass uninverted; a test-side model agrees bit
 *                for bit; descramble(scramble(x)) = x over 10^4 PRBS bits
 *   filters      hst_bbpf: 250-500 Hz flat, >= 50 dB down at 600 Hz and
 *                above (and at 150 Hz and below); hst_hbpf: 600-3400 Hz flat,
 *                >= 40 dB down at 500 Hz and below
 *   tx_phase     known line tribits after the preamble: the phases a
 *                test-side matched correlator measures step by
 *                hst_bstep[t] x 45 degrees and sit on 22.5 + 45 k degrees
 *                (450 at 375 Hz, 300 at 350 Hz; the preamble's symbols too)
 *   tx_speed     450 then 300 by hst_btx_set_speed: the 300 symbols step
 *                right; hst_btx_stop: silence once the pulses have drained
 *   tx_spectrum  10 s of random data at 450 and at 300: power at 600 Hz and
 *                above >= 50 dB below the in-band peak; the occupied band at
 *                -20 dB 274-476 Hz (450) and 283-417 Hz (300) within
 *                +-10 Hz; the line level is the one asked for
 *   loop_450, loop_300  our transmitter, random data, through a line of
 *                sim/resamp (+-100 ppm), a +-7 Hz carrier shift and sim/noise
 *                (white, 20 dB below the signal over 0-4 kHz); four cases
 *                each: locked, and at most one bit in error in 2 x 10^5
 *                after the lock (BER < 1e-5), and no loss of lock after it
 *                (TEST_SHORT: 10^4 bits)
 *   lock_time    the loop_* lines: locked within 300 ms of the
 *                preamble's start at 450, 450 ms at 300
 *   cd           carrier off within 100 ms of the line falling silent (the
 *                transmitter stopped and drained), behind -50 dBm0 noise; no
 *                carrier, no lock and no bits on 10 s of -50 dBm0 noise
 *   line_450, line_300  sim/v32line's line model (mu-law, 6 dB loss, a
 *                dispersive loop, 200 samples of delay, 20 dB SNR, +7 Hz,
 *                +100 ppm): no bit in error in 5 x 10^4 after the lock (the
 *                test that says whether the receiver needs an equaliser;
 *                TEST_SHORT: 2 x 10^3)
 *
 * The output (the golden file) holds exact integers and one pass or fail
 * line per bound; the measured values, from the test's own floating-point
 * arithmetic, only with HST_VERBOSE set. Each case seeds its own random
 * data, so a case run alone prints what it prints in the whole run. */
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include "test.h"
#include "../modem/scramble.h"
#include "../modem/hst_tabs.h"
#include "../modem/hst.h"
#include "../sim/v32line.h"
#include "../sim/noise.h"
#include "../sim/resamp.h"

#define FS 8000
#define PI 3.14159265358979323846

/* ---- a test-side model of the scrambler (facts: out = in ^ out[n-14] ^ out[n-17]) ---- */
typedef struct { uint32_t h; } mscr_t;          /* bit 0 = newest line bit */
static int mscr_line(mscr_t *m, int di)
{
    int ds = (di ^ (int)(m->h >> 13) ^ (int)(m->h >> 16)) & 1;
    m->h = (m->h << 1) | (uint32_t)ds;
    return ds;
}
/* the data bit that puts `ds` on the line next */
static int mscr_data_for(mscr_t *m, int ds)
{
    int di = (ds ^ (int)(m->h >> 13) ^ (int)(m->h >> 16)) & 1;
    m->h = (m->h << 1) | (uint32_t)(ds & 1);
    return di;
}

static int verbose;
/* one bound: its line, and its check */
static void bound(const char *what, int ok)
{
    printf("  %s: %s\n", what, ok ? "pass" : "FAIL");
    CHECK(ok);
}

static uint32_t prbs;
static void prbs_seed(uint32_t s) { prbs = s; }
static int prbs_bit(void)
{
    prbs = prbs * 1664525u + 1013904223u;
    return (int)(prbs >> 27) & 1;
}

/* ---- the transmitter's bit source ---- */
typedef struct {
    mscr_t model;          /* the line's scrambler, followed bit for bit */
    int    nline;          /* line tribits wanted after the preamble, sent cyclically */
    const uint8_t *line;
    int    pos;            /* data bits handed out */
    int    random;         /* random data instead */
    uint8_t *log; long nlog, maxlog;   /* random data: the bits handed out */
} src_t;
static int getbit(void *user)
{
    src_t *s = (src_t *)user;
    int ds;
    if (s->random) {
        int b = prbs_bit();
        if (s->log && s->nlog < s->maxlog) s->log[s->nlog++] = (uint8_t)b;
        return b;
    }
    ds = (s->line[(s->pos / 3) % s->nline] >> (s->pos % 3)) & 1;      /* tribit LSB first */
    s->pos++;
    return mscr_data_for(&s->model, ds);
}
/* a source for `nline` known line tribits, over and over, after a preamble of npre symbols */
static void src_line(src_t *s, const uint8_t *line, int nline, int npre)
{
    int i;
    memset(s, 0, sizeof *s);
    s->line = line; s->nline = nline;
    for (i = 0; i < 3 * npre; i++) (void)mscr_line(&s->model, 1);    /* the preamble's ones */
}
/* the line tribit of symbol k (from the preamble's start), and the scrambler model of the preamble */
static int line_tribit(mscr_t *pre, const uint8_t *line, int nline, int npre, int k)
{
    int b, t = 0;
    if (k >= npre) return line[(k - npre) % nline];
    for (b = 0; b < 3; b++) t |= mscr_line(pre, 1) << b;
    return t;
}

/* ---- the test's own matched filter: RRC, beta 0.35, +-10 symbols, Hann ---- */
static double rrc(double t)
{
    const double a = 0.35;
    if (fabs(t) < 1e-9) return 1 - a + 4 * a / PI;
    if (fabs(fabs(t) - 1 / (4 * a)) < 1e-9)
        return a / sqrt(2) * ((1 + 2 / PI) * sin(PI / (4 * a)) + (1 - 2 / PI) * cos(PI / (4 * a)));
    return (sin(PI * t * (1 - a)) + 4 * a * t * cos(PI * t * (1 + a))) / (PI * t * (1 - 16 * a * a * t * t));
}
#define MFL 10
static double mf(double t) { return fabs(t) >= MFL ? 0 : rrc(t) * (0.5 + 0.5 * cos(PI * t / MFL)); }

/* the phase, in degrees [0, 360), of the symbol centred at sample c (T samples a symbol) */
static double sym_phase(const int16_t *x, int n, double fc, double c, double T)
{
    double re = 0, im = 0, g, ph;
    int i, i0 = (int)floor(c - MFL * T), i1 = (int)ceil(c + MFL * T);
    if (i0 < 0) i0 = 0;
    if (i1 > n - 1) i1 = n - 1;
    for (i = i0; i <= i1; i++) {
        g = mf((i - c) / T) * x[i];
        re += g * cos(2 * PI * fc * i / FS);
        im -= g * sin(2 * PI * fc * i / FS);
    }
    ph = atan2(im, re) * 180 / PI;
    return ph < 0 ? ph + 360 : ph;
}
static double wrap180(double d)
{
    while (d > 180) d -= 360;
    while (d <= -180) d += 360;
    return d;
}

#define NBUF 24000
static int16_t buf[NBUF];

static void steps(void)
{
    static const int row[8] = { 1, 6, 2, 5, 0, 7, 3, 4 };     /* BF §3 */
    const uint32_t fw = 0x43705261u;
    int t;
    for (t = 0; t < 8; t++) {
        CHECK_EQ_I(hst_bstep[t], row[t]);
        CHECK_EQ_I(hst_bstep[t], (fw >> (4 * t)) & 15);
    }
}

static void scr17(void)
{
    scr_t s, d, v;
    mscr_t m = { 0 }, want = { 0 };
    int i, bad = 0, ones = 0, vdiff = 0, di, ds;

    /* data that puts 100 ones in a row on the line, from the zero state */
    scr_init(&s); scr_init(&v);
    for (i = 0; i < 100; i++) {
        di = mscr_data_for(&want, 1);
        ds = scr17_scramble(&s, di);
        ones += ds == 1;
        if (v22_scramble(&v, di) != ds) vdiff++;
    }
    CHECK_EQ_I(ones, 100);          /* no inversion after 64 ones */
    CHECK(vdiff > 0);               /* where v22_scramble inverts */

    /* against the model, and the round trip, over 10^4 PRBS bits */
    prbs_seed(0x1234567u);
    scr_init(&s); scr_init(&d);
    for (i = 0; i < 10000; i++) {
        di = prbs_bit();
        ds = scr17_scramble(&s, di);
        if (ds != mscr_line(&m, di)) bad++;
        if (scr17_descramble(&d, ds) != di) bad++;
    }
    CHECK_EQ_I(bad, 0);
    /* self-synchronising: a descrambler from another state is right after 17 bits */
    scr_init(&s); scr_init(&d); d.reg = 0x15A5Au;
    bad = 0;
    for (i = 0; i < 1000; i++) {
        di = prbs_bit();
        ds = scr17_scramble(&s, di);
        if (scr17_descramble(&d, ds) != di && i >= 17) bad++;
    }
    CHECK_EQ_I(bad, 0);
}

/* |H(f)| in dB of a Q15 FIR */
static double fir_db(const int16_t *h, int n, double f)
{
    double re = 0, im = 0;
    int i;
    for (i = 0; i < n; i++) {
        re += h[i] * cos(2 * PI * f * i / FS);
        im -= h[i] * sin(2 * PI * f * i / FS);
    }
    return 10 * log10((re * re + im * im) / (32768.0 * 32768.0) + 1e-30);
}

static void filters(void)
{
    double f, lo = 1e9, hi = -1e9, stop = -1e9;
    int i, sym = 1;
    for (i = 0; i < HST_BBPF_N; i++) sym &= hst_bbpf[i] == hst_bbpf[HST_BBPF_N - 1 - i];
    for (i = 0; i < HST_HBPF_N; i++) sym &= hst_hbpf[i] == hst_hbpf[HST_HBPF_N - 1 - i];
    CHECK(sym);                                   /* linear phase */

    for (f = 250; f <= 500; f += 2) { double d = fir_db(hst_bbpf, HST_BBPF_N, f); if (d < lo) lo = d; if (d > hi) hi = d; }
    for (f = 600; f <= 4000; f += 2) { double d = fir_db(hst_bbpf, HST_BBPF_N, f); if (d > stop) stop = d; }
    for (f = 0; f <= 150; f += 2) { double d = fir_db(hst_bbpf, HST_BBPF_N, f); if (d > stop) stop = d; }
    printf("bbpf: %d taps\n", HST_BBPF_N);
    if (verbose) printf("  (250-500 Hz %.3f to %.3f dB, <= 150 and >= 600 Hz at most %.2f dB)\n", lo, hi, stop);
    bound("250-500 Hz within 0.5 dB", lo >= -0.5 && hi <= 0.5);
    bound("50 dB down at <= 150 Hz and >= 600 Hz", stop <= -50);

    lo = 1e9; hi = -1e9; stop = -1e9;
    for (f = 600; f <= 3400; f += 2) { double d = fir_db(hst_hbpf, HST_HBPF_N, f); if (d < lo) lo = d; if (d > hi) hi = d; }
    for (f = 0; f <= 500; f += 2) { double d = fir_db(hst_hbpf, HST_HBPF_N, f); if (d > stop) stop = d; }
    printf("hbpf: %d taps\n", HST_HBPF_N);
    if (verbose) printf("  (600-3400 Hz %.3f to %.3f dB, <= 500 Hz at most %.2f dB)\n", lo, hi, stop);
    bound("600-3400 Hz within 0.5 dB", lo >= -0.5 && hi <= 0.5);
    bound("40 dB down at <= 500 Hz", stop <= -40);
}

/* line tribits: every value in turn, then a mixed run */
static void line_tribits(uint8_t *t, int n)
{
    int i;
    for (i = 0; i < n; i++)
        t[i] = (uint8_t)(i < 8 ? i : i < 72 ? ((i - 8) >> 3 ^ (i - 8)) & 7 : (i * 5 + 3) & 7);
}

/* the preamble then known line tribits at `bps`; every symbol's phase */
static void phase_run(int bps)
{
    hst_btx_t tx;
    src_t src;
    mscr_t pre = { 0 };
    uint8_t line[72];
    const int npre = bps == 450 ? 45 : 30, nline = 72, nsym = npre + nline;
    const double T = bps == 450 ? FS / 150.0 : FS / 100.0, fc = bps == 450 ? 375 : 350;
    int k, n, t, p = 0, step_bad = 0, grid_bad = 0;
    double ph, prev = 0, emax_step = 0, emax_grid = 0;

    line_tribits(line, nline);
    src_line(&src, line, nline, npre);
    hst_btx_init(&tx, bps, 4000, getbit, &src);
    hst_btx_preamble(&tx);
    for (n = 0; n < (int)((nsym + HST_BL + MFL + 2) * T) && n < NBUF; n++) buf[n] = hst_btx_tick(&tx);
    for (k = 0; k < nsym; k++) {
        double eg, es;
        t = line_tribit(&pre, line, nline, npre, k);
        p = (p + hst_bstep[t]) & 7;
        ph = sym_phase(buf, n, fc, (k + HST_BL / 2.0) * T, T);
        eg = fabs(wrap180(ph - (22.5 + 45 * p)));
        es = k ? fabs(wrap180(ph - prev - 45 * hst_bstep[t])) : 0;
        if (eg > emax_grid) emax_grid = eg;
        if (es > emax_step) emax_step = es;
        grid_bad += eg > 3;
        step_bad += es > 3;
        prev = ph;
    }
    printf("tx_phase %d: %d symbols (%d preamble)\n", bps, nsym, npre);
    if (verbose) printf("  (step error at most %.3f deg, grid error at most %.3f deg)\n", emax_step, emax_grid);
    bound("every step hst_bstep[t] x 45 deg within 3 deg", step_bad == 0);
    bound("every symbol on 22.5 + 45 k deg within 3 deg", grid_bad == 0);
    CHECK(src.pos >= 3 * nline);
}

static void tx_phase(void)
{
    phase_run(450);
    phase_run(300);
}

static void tx_speed(void)
{
    hst_btx_t tx;
    src_t src;
    mscr_t pre = { 0 };
    uint8_t line[72];
    int n, k, n300 = -1, s450 = 0, t, p = 0, tail = 0, bad = 0;
    double ph, prev = 0;

    line_tribits(line, 72);
    src_line(&src, line, 72, 45);
    hst_btx_init(&tx, 450, 4000, getbit, &src);
    hst_btx_preamble(&tx);
    for (n = 0; n < 3000; n++) buf[n] = hst_btx_tick(&tx);
    hst_btx_set_speed(&tx, 300);
    for (; n < 12000; n++) {
        buf[n] = hst_btx_tick(&tx);
        if (n300 < 0 && tx.newsym && tx.bps == 300) n300 = n;
    }
    CHECK(n300 >= 3000 && n300 <= 3000 + 54);       /* at the next 450 symbol */
    /* 450 symbols began at 0, 53 1/3, ... before n300 */
    while (s450 * (FS / 150.0) < n300 - 0.01) s450++;
    for (k = 0; k < s450; k++) p = (p + hst_bstep[line_tribit(&pre, line, 72, 45, k)]) & 7;
    for (k = 0; k < 60; k++) {
        t = line_tribit(&pre, line, 72, 45, s450 + k);
        p = (p + hst_bstep[t]) & 7;
        ph = sym_phase(buf, n, 350, n300 + (k + HST_BL / 2.0) * 80, 80);
        /* from the 12th, the measurement's window is clear of the 450 tail */
        if (k > 12 && fabs(wrap180(ph - prev - 45 * hst_bstep[t])) > 3) bad++;
        if (k >= 12 && fabs(wrap180(ph - (22.5 + 45 * p))) > 3) bad++;
        prev = ph;
    }
    printf("tx_speed: 450 -> 300 at sample %d, after %d symbols at 450\n", n300, s450);
    bound("the 300 symbols' steps and grid within 3 deg", bad == 0);

    hst_btx_stop(&tx);
    for (n = 0; n < (HST_BL + 1) * 80; n++) (void)hst_btx_tick(&tx);
    for (n = 0; n < 1000; n++) tail |= hst_btx_tick(&tx);
    bound("silence once the pulses have drained", tail == 0);
}

/* floor(sqrt(v)) */
static int64_t isqrt64(int64_t v)
{
    int64_t r = (int64_t)sqrt((double)v);
    while (r * r > v) r--;
    while ((r + 1) * (r + 1) <= v) r++;
    return r;
}

/* ---- spectrum: Welch, Hann, 4096 points, half overlap ---- */
#define NF 4096
static void fft(double *re, double *im, int n)
{
    int i, j, k, len;
    for (i = 1, j = 0; i < n; i++) {
        int bit = n >> 1;
        for (; j & bit; bit >>= 1) j ^= bit;
        j ^= bit;
        if (i < j) { double t = re[i]; re[i] = re[j]; re[j] = t; t = im[i]; im[i] = im[j]; im[j] = t; }
    }
    static double twr[NF / 2], twi[NF / 2];
    if (twi[1] == 0)
        for (k = 0; k < NF / 2; k++) { twr[k] = cos(-2 * PI * k / NF); twi[k] = sin(-2 * PI * k / NF); }
    for (len = 2; len <= n; len <<= 1) {
        for (i = 0; i < n; i += len)
            for (k = 0; k < len / 2; k++) {
                double wr = twr[k * (NF / len)], wi = twi[k * (NF / len)];
                double xr = re[i + k + len / 2] * wr - im[i + k + len / 2] * wi;
                double xi = re[i + k + len / 2] * wi + im[i + k + len / 2] * wr;
                re[i + k + len / 2] = re[i + k] - xr; im[i + k + len / 2] = im[i + k] - xi;
                re[i + k] += xr; im[i + k] += xi;
            }
    }
}

static void spectrum_run(int bps, double lo_want, double hi_want)
{
    static double re[NF], im[NF], psd[NF / 2 + 1];
    static int16_t x[10 * FS];
    hst_btx_t tx;
    src_t src;
    int n, i, seg, nseg = 0, pk = 0, lo, hi;
    int64_t sq = 0, rms;
    double peak, out = 0, hz = (double)FS / NF;

    prbs_seed(0x2468ACEu + (uint32_t)bps);
    memset(&src, 0, sizeof src);
    src.random = 1;
    hst_btx_init(&tx, bps, 4000, getbit, &src);
    hst_btx_preamble(&tx);
    for (n = 0; n < FS; n++) (void)hst_btx_tick(&tx);         /* past the preamble */
    for (n = 0; n < 10 * FS; n++) { x[n] = hst_btx_tick(&tx); sq += (int64_t)x[n] * x[n]; }
    rms = isqrt64(sq / (10 * FS));

    memset(psd, 0, sizeof psd);
    for (seg = 0; seg + NF <= 10 * FS; seg += NF / 2, nseg++) {
        for (i = 0; i < NF; i++) {
            re[i] = x[seg + i] * (0.5 - 0.5 * cos(2 * PI * i / NF));
            im[i] = 0;
        }
        fft(re, im, NF);
        for (i = 0; i <= NF / 2; i++) psd[i] += re[i] * re[i] + im[i] * im[i];
    }
    for (i = 0; i <= NF / 2; i++) if (psd[i] > psd[pk]) pk = i;
    peak = psd[pk];
    for (i = (int)ceil(600 / hz); i <= NF / 2; i++) if (psd[i] > out) out = psd[i];
    for (lo = pk; lo > 0 && psd[lo - 1] >= peak / 100; lo--) ;
    for (hi = pk; hi < NF / 2 && psd[hi + 1] >= peak / 100; hi++) ;
    printf("tx_spectrum %d: level %d (asked 4000), %d segments\n", bps, (int)rms, nseg);
    if (verbose)
        printf("  (peak at %.1f Hz, -20 dB band %.1f-%.1f Hz, >= 600 Hz %.2f dB)\n",
               pk * hz, lo * hz, hi * hz, 10 * log10(out / peak));
    bound("level within 0.3 dB of 4000", rms >= 3863 && rms <= 4141);     /* 4000 x 10^(-+0.3/20) */
    bound(">= 600 Hz at least 50 dB below the peak", 10 * log10(out / peak) <= -50);
    {
        char what[64];
        snprintf(what, sizeof what, "-20 dB band within 10 Hz of %d-%d Hz", (int)lo_want, (int)hi_want);
        bound(what, fabs(lo * hz - lo_want) <= 10 && fabs(hi * hz - hi_want) <= 10);
    }
    CHECK(nseg >= 30);
}

static void tx_spectrum(void)
{
    spectrum_run(450, 274, 476);
    spectrum_run(300, 283, 417);
}

/* ---- the receiver (Task 12): our transmitter through a line ---- */
#define LEVEL 4000                     /* the transmitter's RMS, about -12 dBm0 */
#ifdef TEST_SHORT
#define NBITS 10000L
#define NBITS_LINE 2000L
#else
#define NBITS 200000L
#define NBITS_LINE 50000L
#endif
#define LOGN (NBITS + 4000)
static uint8_t txlog[LOGN], rxlog[LOGN];

static double dbm0_of(double rms) { return 20 * log10(rms / v32line_rms(0)); }
/* |H(f)| of a loop filter */
static double loop_gain(const double *h, int n, double f)
{
    double re = 0, im = 0;
    int i;
    for (i = 0; i < n; i++) { re += h[i] * cos(2 * PI * f * i / FS); im -= h[i] * sin(2 * PI * f * i / FS); }
    return sqrt(re * re + im * im);
}
static double peer_tx(void *user, double rx) { (void)rx; return hst_btx_tick((hst_btx_t *)user); }

/* The loop_* line: the caller's clock (sim/resamp, linear: its error is
 * some -46 dB at 500 Hz), a frequency shift (a Hilbert transformer, 63
 * taps, Hamming, as sim/v32line's; the carrier by a recursive rotation,
 * set again every 1024 samples), and sim/noise's white noise. A lighter
 * line than v32line's, whose two windowed-sinc resamplers cost some 200
 * libm calls a sample. */
#define HILN 63
typedef struct {
    resamp_t rs;
    rng_t    g;
    double   nrms, w, c, s;
    double   hil[HILN], h[HILN];
    int      hp;
    long     n;
} chan_t;
static void chan_init(chan_t *ch, double hz, double ppm, double nrms, uint32_t seed)
{
    int i;
    memset(ch, 0, sizeof *ch);
    resamp_init(&ch->rs, 1.0 / ppm_ratio(ppm));
    rng_seed(&ch->g, seed);
    ch->nrms = nrms;
    ch->w = 2 * PI * hz / FS;
    ch->c = 1;
    for (i = 0; i < HILN; i++) {
        int k = i - HILN / 2;
        ch->hil[i] = (k & 1) ? 2.0 / (PI * k) * (0.54 + 0.46 * cos(2 * PI * k / (HILN - 1))) : 0.0;
    }
}
/* one sample from the caller; the line's samples (0, 1 or 2) to out */
static int chan_push(chan_t *ch, double x, int16_t *out)
{
    double r[4], im, re, v;
    int n = resamp_push(&ch->rs, x, r, 4), i, j;
    for (i = 0; i < n; i++) {
        ch->hp = (ch->hp + 1) % HILN;
        ch->h[ch->hp] = r[i];
        re = ch->h[(ch->hp - HILN / 2 + HILN) % HILN];
        for (im = 0, j = 0; j < HILN; j += 2) im += ch->hil[j] * ch->h[(ch->hp - j + HILN) % HILN];   /* odd k = j - 31 */
        if ((ch->n & 1023) == 0) { ch->c = cos(ch->w * ch->n); ch->s = sin(ch->w * ch->n); }
        v = re * ch->c - im * ch->s + rng_gauss(&ch->g) * ch->nrms;
        { double c = ch->c * cos(ch->w) - ch->s * sin(ch->w); ch->s = ch->s * cos(ch->w) + ch->c * sin(ch->w); ch->c = c; }
        ch->n++;
        out[i] = (int16_t)lrint(v > 32767 ? 32767 : v < -32768 ? -32768 : v);
    }
    return n;
}

typedef struct {
    int    bps;
    double hz, ppm;                    /* carrier shift, the caller's clock */
    int    mulaw;                      /* v32line's line model: mu-law, loss, loop, delay */
    uint32_t seed;
    double snr;                        /* dB below the signal over 0-4 kHz (0: 20) */
    double pre;                        /* seconds of the line's noise before the transmitter starts */
    double drop_at, drop_len;          /* seconds after it starts: the signal off, the noise on */
    double snr2, at2;                  /* the noise rises to snr2 dB below the signal at at2 s (snr2 0: never) */
    int    all;                        /* every bit given counts (each lock aligned on its own), not
                                        * only those after the last lock */
} line_t;

typedef struct {
    long   lock_at;                    /* samples from the preamble's arrival to the lock; -1: never */
    long   nbits, errors;              /* bits compared after the lock, and in error */
    int    unlocks;                    /* losses of lock after it */
    int    unlocks_drop;               /* of them, from the dropout's start */
    int    unlocks_bits;               /* of them, once bits have come (after the lock's second check) */
    int    cd_lost;
    long   snr_num, snr_den;
    int    locked_end;                 /* locked at the end */
    double hz_err;                     /* the receiver's carrier at the end against the line's, Hz */
} run_t;

/* the receiver's view of one line sample */
typedef struct {
    hst_brx_t rx;
    run_t    *o;
    long      n, nrx, arrive;
    long      restart;                 /* the sample from which the bits count again (0: none) */
    int       was, all, epoch;
    long      drop;                    /* the sample the dropout reaches the receiver (0: none) */
    int       flowing;                 /* bits have come */
} watch_t;
static int16_t rxepo[LOGN];            /* the lock each received bit came in */
static int32_t rxn[LOGN];              /* and the line sample it came out at */
static void watch(watch_t *w, int16_t x)
{
    int nb = hst_brx_tick(&w->rx, x), lk = hst_brx_locked(&w->rx), k;
    if (lk && w->o->lock_at < 0) w->o->lock_at = w->n - w->arrive;
    if (w->was && !lk) {
        w->o->unlocks++;
        if (w->drop && w->n >= w->drop) w->o->unlocks_drop++;
        if (w->flowing) w->o->unlocks_bits++;
    }
    if (nb) w->flowing = 1;
    if (w->o->lock_at >= 0 && !hst_brx_cd(&w->rx)) w->o->cd_lost = 1;
    if (lk && !w->was) w->epoch++;
    if (!w->all && ((lk && !w->was) || w->n == w->restart)) w->nrx = 0;   /* the bits from the last lock, or the dropout's end */
    w->was = lk;
    if (w->o->lock_at >= 0)
        for (k = 0; k < nb && w->nrx < LOGN; k++) {
            rxepo[w->nrx] = (int16_t)w->epoch; rxn[w->nrx] = (int32_t)w->n;
            rxlog[w->nrx++] = w->rx.bits[k];
        }
    w->n++;
}

/* every received bit, each lock's on its own: aligned by a 64-bit match
 * (before the data, the preamble's ones); a lock with too few bits for
 * that is placed by time from an aligned one (the bit rate, +-6 bits) */
static int expect_bit(long t, long nlog) { return t < 0 ? 1 : t < nlog ? txlog[t] : -1; }
static void score_epochs(long nrx, long nlog, int bps, run_t *o)
{
    long i, abase = 0, an = 0;
    int anchored = 0, pass;
    o->nbits = o->errors = 0;
    for (pass = 0; pass < 2; pass++)
        for (i = 0; i < nrx; ) {
            long j = i, off, base = 0, k, q, d, e, emin;
            int found = 0;
            while (j < nrx && rxepo[j] == rxepo[i]) j++;
            for (q = i; q + 64 <= j && !found && q < i + 400; q++)
                for (off = 0; off + 64 < nlog && !found; off++) {
                    for (k = 0; k < 64 && rxlog[q + k] == txlog[off + k]; k++) ;
                    if (k == 64) { found = 1; base = off - (q - i); }
                }
            if (pass == 0) {
                if (found && !anchored) { anchored = 1; abase = base; an = rxn[i]; }
            } else if (found) {
                for (k = i; k < j; k++) o->errors += rxlog[k] != expect_bit(base + (k - i), nlog);
                o->nbits += j - i;
            } else {
                long pred = abase + (long)((double)(rxn[i] - an) * bps / FS + 0.5);
                emin = j - i;
                for (d = -6; anchored && d <= 6; d++) {
                    for (e = 0, k = i; k < j; k++) e += rxlog[k] != expect_bit(pred + d + (k - i), nlog);
                    if (e < emin) emin = e;
                }
                o->errors += emin;
                o->nbits += j - i;
            }
            i = j;
        }
}

/* the transmitter's preamble then random data through the line; the
 * receiver's bits from its lock compared with the data, `want` of them
 * (0: run `secs` seconds and only time the lock) */
static void run_line(const line_t *ln, long want, double secs, run_t *o)
{
    static const double loop[] = { 0.3, 1.0, -0.5, 0.3 };     /* test_v22bis's "mild" loop */
    static v32line_t L;
    static chan_t ch;
    static watch_t W;
    v32line_cfg lc;
    hst_btx_t tx;
    src_t src;
    long nmax;

    memset(o, 0, sizeof *o);
    o->lock_at = -1;
    memset(&W, 0, sizeof W);
    W.o = o;
    W.all = ln->all;
    if (ln->mulaw) {
        memset(&lc, 0, sizeof lc);
        lc.mulaw = 1; lc.loss_db = 6; lc.delay = 200; lc.taps = loop; lc.ntaps = 4;
        lc.near_db = lc.far_db = lc.c_near_db = lc.c_far_db = 300;
        lc.noise_c_dbm0 = -300;
        lc.noise_a_dbm0 = dbm0_of(LEVEL * pow(10, -6 / 20.0) * loop_gain(loop, 4, ln->bps == 450 ? 375 : 350)) - 20;
        lc.freq_offset = ln->hz;
        lc.ppm = ln->ppm;
        lc.seed = ln->seed;
        v32line_init(&L, &lc);
        W.arrive = L.oneway;
    } else {
        chan_init(&ch, ln->hz, ln->ppm, LEVEL * pow(10, -(ln->snr > 0 ? ln->snr : 20) / 20), ln->seed);
        W.arrive = HILN / 2 + 1 + (long)(ln->pre * FS);
        if (ln->drop_len > 0) {
            W.restart = W.arrive + (long)((ln->drop_at + ln->drop_len) * FS);
            W.drop = W.arrive + (long)(ln->drop_at * FS);
        }
    }

    prbs_seed(ln->seed * 2654435761u + 77);
    memset(&src, 0, sizeof src);
    src.random = 1;
    src.log = txlog; src.maxlog = LOGN;
    hst_btx_init(&tx, ln->bps, LEVEL, getbit, &src);
    hst_btx_preamble(&tx);
    hst_brx_init(&W.rx, ln->bps);

    nmax = want ? (long)((want + 3000) * FS / (double)ln->bps) + 4 * FS : (long)(secs * FS);
    nmax += (long)((ln->pre + ln->drop_at + ln->drop_len) * FS);
    if (ln->all) nmax = (long)(secs * FS);
    while (W.n < nmax) {
        if (ln->mulaw) watch(&W, v32line_tick(&L, 0, peer_tx, &tx));
        else {
            int16_t y[4];
            double t = W.n / (double)FS - ln->pre, v = 0;
            int k, m;
            if (ln->snr2 > 0 && t >= ln->at2) ch.nrms = LEVEL * pow(10, -ln->snr2 / 20);
            if (t >= 0) {
                v = hst_btx_tick(&tx);
                if (t >= ln->drop_at && t < ln->drop_at + ln->drop_len) v = 0;
            }
            m = chan_push(&ch, v, y);
            for (k = 0; k < m; k++) watch(&W, y[k]);
        }
        if (want && !ln->all && W.nrx >= want + 400 && src.nlog > want + 400) break;
    }
    {
        int64_t num = 0, den = 0;
        if (o->lock_at >= 0 && hst_brx_snr(&W.rx, &num, &den)) { o->snr_num = (long)num; o->snr_den = (long)den; }
    }
    o->locked_end = hst_brx_locked(&W.rx);
    o->hz_err = (double)(int32_t)(W.rx.dph - W.rx.dph0) * 1600 / 4294967296.0
              + (double)W.rx.wturn * (ln->bps == 450 ? 150 : 100) / 4294967296.0 - ln->hz;
    if (ln->all) { score_epochs(W.nrx, src.nlog, ln->bps, o); return; }
    if (!want || o->lock_at < 0 || W.nrx < want + 400) return;
    /* the data's place in the received bits: 64 bits from the 400th, found in the log */
    {
        long off, best = -1, j, i0 = 400;
        for (off = 0; off + 64 < src.nlog && best < 0; off++) {
            for (j = 0; j < 64 && rxlog[i0 + j] == txlog[off + j]; j++) ;
            if (j == 64) best = off;
        }
        if (best < 0) { o->nbits = 0; o->errors = want; return; }
        /* rxlog[i] is txlog[best - i0 + i]; before the data, the preamble's ones */
        for (j = 0; j < want; j++) {
            long t = best - i0 + j;
            int expect = t < 0 ? 1 : txlog[t];
            if (t >= src.nlog) break;
            o->errors += rxlog[j] != expect;
            o->nbits++;
        }
    }
}

static const struct { double hz, ppm; } offs[4] = { { 7, 100 }, { 7, -100 }, { -7, 100 }, { -7, -100 } };

static void loop_case(int bps, int c, int mulaw)
{
    line_t ln;
    run_t o;
    long want = mulaw ? NBITS_LINE : NBITS;
    memset(&ln, 0, sizeof ln);
    ln.bps = bps; ln.hz = offs[c].hz; ln.ppm = offs[c].ppm; ln.mulaw = mulaw;
    ln.seed = (uint32_t)(bps * 10 + c + 1 + 100 * mulaw);
    run_line(&ln, want, 0, &o);
    printf("%s_%d %+d Hz %+d ppm: %ld bits compared after the lock\n", mulaw ? "line" : "loop",
           bps, (int)ln.hz, (int)ln.ppm, o.nbits);
    if (verbose)
        printf("  (locked %.1f ms after the preamble's start, %ld errors, snr %.1f dB)\n",
               o.lock_at * 1000.0 / FS, o.errors,
               o.snr_den ? 10 * log10((double)o.snr_num / o.snr_den) : 0.0);
    bound("locked", o.lock_at >= 0);
    bound(mulaw ? "no bit in error" : "BER < 1e-5 (at most one error)", o.nbits == want && o.errors * 100000L < o.nbits);
    bound("no loss of lock or carrier once the bits come", o.unlocks_bits == 0 && !o.cd_lost);
}

static void lock_time(void)
{
    int s, c;
    for (s = 0; s < 2; s++) {
        int bps = s ? 300 : 450;
        long lim = (s ? 450 : 300) * FS / 1000, worst = 0;
        int late = 0;
        for (c = 0; c < 4; c++) {
            line_t ln;
            run_t o;
            memset(&ln, 0, sizeof ln);
            ln.bps = bps; ln.hz = offs[c].hz; ln.ppm = offs[c].ppm; ln.mulaw = 0;
            ln.seed = (uint32_t)(500 + bps + c);
            run_line(&ln, 0, 1.5, &o);
            if (o.lock_at < 0 || o.lock_at > lim) late++;
            if (o.lock_at > worst) worst = o.lock_at;
            if (o.lock_at < 0) worst = 1L << 30;
        }
        printf("lock_time %d: 4 lines\n", bps);
        if (verbose) printf("  (latest lock %.1f ms after the preamble's start)\n", worst * 1000.0 / FS);
        bound(s ? "locked within 450 ms on every line" : "locked within 300 ms on every line", late == 0);
    }
}

static void cd(void)
{
    rng_t g;
    int s;
    long n;
    double nrms = v32line_rms(-50);
    for (s = 0; s < 2; s++) {
        int bps = s ? 300 : 450, on = 0, lk = 0, bits = 0;
        hst_btx_t tx;
        hst_brx_t rx;
        src_t src;
        long last = -1, off_at = -1, stop_at;
        /* noise alone */
        rng_seed(&g, 1000u + (uint32_t)bps);
        hst_brx_init(&rx, bps);
        for (n = 0; n < 10 * FS; n++) {
            double v = rng_gauss(&g) * nrms;
            bits += hst_brx_tick(&rx, (int16_t)lrint(v));
            on |= hst_brx_cd(&rx);
            lk |= hst_brx_locked(&rx);
        }
        printf("cd %d: 10 s of -50 dBm0 noise\n", bps);
        bound("no carrier, no lock, no bits", !on && !lk && bits == 0);
        /* 2 s of signal behind that noise, then the transmitter stops */
        prbs_seed(0x5151u + (uint32_t)bps);
        memset(&src, 0, sizeof src);
        src.random = 1;
        hst_btx_init(&tx, bps, LEVEL, getbit, &src);
        hst_btx_preamble(&tx);
        hst_brx_init(&rx, bps);
        on = 0;
        stop_at = 2 * FS;
        for (n = 0; n < 3 * FS; n++) {
            int16_t t;
            if (n == stop_at) hst_btx_stop(&tx);
            t = hst_btx_tick(&tx);
            if (t != 0) last = n;
            hst_brx_tick(&rx, (int16_t)lrint(t + rng_gauss(&g) * nrms));
            if (n < stop_at && hst_brx_cd(&rx)) on = 1;
            if (n > stop_at && off_at < 0 && !hst_brx_cd(&rx)) off_at = n;
        }
        printf("cd %d: 2 s of signal, then silence\n", bps);
        if (verbose) printf("  (carrier off %.1f ms after the last sample)\n", (off_at - last) * 1000.0 / FS);
        bound("carrier on with the signal", on);
        bound("carrier off within 100 ms of the silence", off_at > last && off_at - last <= FS / 10);
    }
}

/* ---- what comes before the signal, and what is not one (review round 1) ---- */
#ifdef TEST_SHORT
#define NSEEDS 2
#define NOISE_SECS 6
#else
#define NSEEDS 8
#define NOISE_SECS 60
#endif
#define RELOCK_BITS 1500L
static const double offs3[3] = { 7, -7, 3 };

/* NSEEDS x 3 lines (+7, -7, +3 Hz; +100 ppm): the ones not locked at the
 * end on the right carrier (within 1 Hz) with every one of RELOCK_BITS
 * bits right after the last lock (or after the dropout's end) */
static int relock_bad(int bps, double pre, double drop_len, double snr)
{
    int seed, c, bad = 0;
    for (seed = 1; seed <= NSEEDS; seed++)
        for (c = 0; c < 3; c++) {
            line_t ln;
            run_t o;
            memset(&ln, 0, sizeof ln);
            ln.bps = bps; ln.hz = offs3[c]; ln.ppm = 100; ln.snr = snr;
            ln.pre = pre; ln.drop_at = drop_len > 0 ? 2.0 : 0; ln.drop_len = drop_len;
            ln.seed = (uint32_t)(7000 + 100 * seed + 10 * c + (int)(snr + 10 * drop_len) + bps);
            run_line(&ln, RELOCK_BITS, 0, &o);
            if (!(o.locked_end && fabs(o.hz_err) < 1 && o.nbits == RELOCK_BITS && o.errors == 0)) bad++;
            if (verbose && (o.errors || fabs(o.hz_err) >= 1))
                printf("  (seed %d %+.0f Hz: %ld errors, carrier %+.2f Hz off)\n", seed, offs3[c], o.errors, o.hz_err);
        }
    return bad;
}

/* the line's noise for a second before the caller starts (the carrier
 * detect on, an acquisition on noise): 20, 15 and 10 dB */
static void noise_first(void)
{
    int s, bad;
    for (s = 0; s < 2; s++) {
        int bps = s ? 300 : 450;
        bad = relock_bad(bps, 1.0, 0, 20) + relock_bad(bps, 1.0, 0, 15) + relock_bad(bps, 1.0, 0, 10);
        printf("noise_first %d: %d lines, 1 s of noise first at 20, 15 and 10 dB\n", bps, 9 * NSEEDS);
        bound("each locked on the right carrier, no bit in error after the lock", bad == 0);
    }
}

/* the signal off for 0.1, 0.3 and 1 s, the noise on (20 dB) */
static void dropout(void)
{
    int s, bad;
    for (s = 0; s < 2; s++) {
        int bps = s ? 300 : 450;
        bad = relock_bad(bps, 0, 0.1, 20) + relock_bad(bps, 0, 0.3, 20) + relock_bad(bps, 0, 1.0, 20);
        printf("dropout %d: %d lines, the signal off 0.1, 0.3 and 1 s\n", bps, 9 * NSEEDS);
        bound("each locked again on the right carrier, no bit in error after the dropout", bad == 0);
    }
}

static int ones30(uint32_t v)
{
    int n = 0, i;
    for (i = 0; i < 30; i++) n += (int)((v >> i) & 1);
    return n;
}

/* one input to a fresh receiver for `secs`: its locks, its bits and the
 * detector's windows (24 of the last 30 decisions grid_ok) */
typedef struct { long locks, bits, gok; } quiet_t;     /* gok: detector windows, 24 of 30 decisions grid_ok */
static void quiet_add(quiet_t *q, int bps, int kind, double dbm0, double secs, uint32_t seed)
{
    static hst_brx_t rx;
    rng_t g;
    double rms = 15770 * pow(10, dbm0 / 20);
    long n;
    int was = 0, nsym = 0;
    uint32_t hist = 0;
    rng_seed(&g, seed);
    hst_brx_init(&rx, bps);
    for (n = 0; n < (long)(secs * FS); n++) {
        double t = n / (double)FS, v;
        int nb, lk;
        switch (kind) {
        case 0: v = rng_gauss(&g) * rms; break;                                  /* white, 0-4 kHz */
        case 1: v = rms * (sin(2 * PI * 350 * t) + sin(2 * PI * 440 * t)); break; /* US dial tone */
        case 2: v = rms * (sin(2 * PI * 60 * t) + 0.5 * sin(2 * PI * 180 * t)      /* mains hum */
                         + 0.3 * sin(2 * PI * 300 * t) + 0.3 * sin(2 * PI * 420 * t)); break;
        default: v = rms * sqrt(2) * sin(2 * PI * 375 * t); break;              /* the 450 carrier */
        }
        if (kind) v += rng_gauss(&g) * rms * 0.01;
        nb = hst_brx_tick(&rx, (int16_t)lrint(v > 32767 ? 32767 : v < -32768 ? -32768 : v));
        lk = hst_brx_locked(&rx);
        q->locks += lk && !was;
        q->bits += nb;
        if (rx.nsym != nsym) {                              /* a decision */
            nsym = rx.nsym;
            hist = (hist << 1) | (uint32_t)hst_brx_grid_ok(&rx);
            q->gok += ones30(hist) >= 24;
        }
        was = lk;
    }
}

/* dial tone, hum and a 375 Hz tone: never a lock, a bit, or the
 * detector's 24 grid_ok decisions of 30 */
static void tones(void)
{
    int s, k, l;
    for (s = 0; s < 2; s++) {
        int bps = s ? 300 : 450;
        quiet_t q = { 0, 0, 0 };
        for (k = 1; k <= 3; k++)
            for (l = 0; l < 3; l++) {
                quiet_t q1 = { 0, 0, 0 };
                quiet_add(&q1, bps, k, -30 + 10 * l, NOISE_SECS / 2.0, (uint32_t)(k * 10 + l));
                if (verbose && (q1.locks || q1.bits || q1.gok))
                    printf("  (input %d at %d dBm0: %ld locks, %ld bits, %ld windows)\n", k, -30 + 10 * l, q1.locks, q1.bits, q1.gok);
                q.locks += q1.locks; q.bits += q1.bits; q.gok += q1.gok;
            }
        printf("tones %d: US dial tone, mains hum, 375 Hz; at -30, -20 and -10 dBm0, %d s each\n", bps, NOISE_SECS / 2);
        bound("never locked, no bits, grid_ok never on 24 of 30 decisions", q.locks == 0 && q.bits == 0 && q.gok == 0);
    }
}

/* white noise at -31 to -10 dBm0 over 0-4 kHz (-42 to -21 in band):
 * false locks a minute */
static void noise_locks(void)
{
    static const double lv[5] = { -31, -25, -20, -15, -10 };
    int s, l;
    for (s = 0; s < 2; s++) {
        int bps = s ? 300 : 450;
        quiet_t q = { 0, 0, 0 };
        for (l = 0; l < 5; l++) quiet_add(&q, bps, 0, lv[l], NOISE_SECS, (uint32_t)(900 + bps + l));
        printf("noise %d: white noise at -31 to -10 dBm0, %d s each: %ld false locks a minute\n",
               bps, NOISE_SECS, q.locks * 60 / (5 * NOISE_SECS));
        bound("no lock, no bits, grid_ok never on 24 of 30 decisions", q.locks == 0 && q.bits == 0 && q.gok == 0);
    }
}

/* hst_brx_band: a 300 receiver on a 450 receiver's band-pass does what
 * one on its own does */
static void band(void)
{
    static chan_t ch;
    static hst_brx_t a, b, c;
    hst_btx_t tx;
    src_t src;
    long n = 0, diff = 0, bits = 0;
    prbs_seed(0xBA4Du);
    memset(&src, 0, sizeof src);
    src.random = 1;
    hst_btx_init(&tx, 300, LEVEL, getbit, &src);
    hst_btx_preamble(&tx);
    chan_init(&ch, 7, 100, LEVEL / 10.0, 41);
    hst_brx_init(&a, 450); hst_brx_init(&b, 300); hst_brx_init(&c, 300);
    while (n < 3 * FS) {
        int16_t y[4];
        int k, m = chan_push(&ch, hst_btx_tick(&tx), y);
        for (k = 0; k < m; k++, n++) {
            int nb = 0, nc, j;
            hst_brx_tick(&a, y[k]);
            if (a.dec == 0) nb = hst_brx_band(&b, a.y);
            nc = hst_brx_tick(&c, y[k]);
            diff += nb != nc || hst_brx_locked(&b) != hst_brx_locked(&c);
            for (j = 0; j < nb && j < nc; j++) diff += b.bits[j] != c.bits[j];
            bits += nc;
        }
    }
    printf("band: 3 s of 300 through one band-pass, %s\n", bits > 0 ? "bits out" : "no bits");
    bound("the same bits and lock as a receiver on its own", diff == 0 && bits > 0);
}

/* carrier detect about its thresholds (on at -44 dBm0, off under -47),
 * the signal alone */
static void cd_level(void)
{
    int s;
    for (s = 0; s < 2; s++) {
        int bps = s ? 300 : 450, step, on_late = 0, held = 1, off_late = 0, never = 1;
        static const double lv[3] = { -41, -45.5, -50 };
        hst_btx_t tx;
        hst_brx_t rx;
        src_t src;
        long n, on_at = -1, off_at = -1;
        prbs_seed(0xCDu + (uint32_t)bps);
        memset(&src, 0, sizeof src);
        src.random = 1;
        hst_btx_init(&tx, bps, LEVEL, getbit, &src);
        hst_btx_preamble(&tx);
        hst_brx_init(&rx, bps);
        /* -41 for 1 s, -45.5 for 1 s, -50 for 1 s */
        for (n = 0; n < 3 * FS; n++) {
            double g;
            step = (int)(n / FS);
            g = 15770 * pow(10, lv[step] / 20) / LEVEL;
            hst_brx_tick(&rx, (int16_t)lrint(hst_btx_tick(&tx) * g));
            if (on_at < 0 && hst_brx_cd(&rx)) on_at = n;
            if (step == 1 && !hst_brx_cd(&rx)) held = 0;
            if (step == 2 && off_at < 0 && !hst_brx_cd(&rx)) off_at = n;
        }
        on_late = on_at < 0 || on_at > FS / 10;
        off_late = off_at < 0 || off_at - 2 * FS > FS / 10;
        /* from the start: -45.5 and -50 never turn it on */
        for (step = 1; step < 3; step++) {
            hst_brx_init(&rx, bps);
            for (n = 0; n < 2 * FS; n++) {
                double g = 15770 * pow(10, lv[step] / 20) / LEVEL;
                hst_brx_tick(&rx, (int16_t)lrint(hst_btx_tick(&tx) * g));
                if (hst_brx_cd(&rx)) never = 0;
            }
        }
        printf("cd_level %d: the signal at -41, -45.5 and -50 dBm0\n", bps);
        bound("on at -41 within 100 ms", !on_late);
        bound("held at -45.5", held);
        bound("off at -50 within 100 ms", !off_late);
        bound("never on at -45.5 or -50 from the start", never);
    }
}

#ifdef TEST_SHORT
#define HOLD_SECS 10
#else
#define HOLD_SECS 60
#endif

/* hard starts: 1 s of noise first, or a 1 s dropout, at 12 dB; offsets
 * -10 to +10 Hz: no bit given from a lock 45 degrees off, nor any other
 * wrong bit, in all the bits given */
static void alias(void)
{
    static const double hz[7] = { -10, -7, -3, 0, 3, 7, 10 };
    int s, seed, c, cond, bad, runs;
    for (s = 0; s < 2; s++) {
        int bps = s ? 300 : 450;
        bad = runs = 0;
        for (cond = 0; cond < 2; cond++)
            for (seed = 1; seed <= NSEEDS; seed++)
                for (c = 0; c < 7; c++) {
                    line_t ln;
                    run_t o;
                    memset(&ln, 0, sizeof ln);
                    ln.bps = bps; ln.hz = hz[c]; ln.ppm = seed & 1 ? 100 : -100; ln.snr = 12; ln.all = 1;
                    if (cond == 0) ln.pre = 1.0; else { ln.drop_at = 2.0; ln.drop_len = 1.0; }
                    ln.seed = (uint32_t)(8000 + 100 * seed + 10 * c + cond + bps);
                    run_line(&ln, 1, 8.0, &o);
                    runs++;
                    if (!(o.locked_end && fabs(o.hz_err) < 1 && o.errors == 0 && o.nbits > 0)) bad++;
                    if (verbose && (o.errors || !o.locked_end || fabs(o.hz_err) >= 1))
                        printf("  (%s seed %d %+.0f Hz: %ld wrong of %ld, carrier %+.2f Hz off, locked %d)\n",
                               cond ? "dropout" : "noise first", seed, hz[c], o.errors, o.nbits, o.hz_err, o.locked_end);
                }
        printf("alias %d: %d hard starts at 12 dB (noise first, a 1 s dropout)\n", bps, runs);
        bound("each locked on the right carrier; not one wrong bit given", bad == 0);
    }
}

/* the signal off 20, 30 and 50 ms (a lost packet or two): the lock held,
 * few wrong bits; 0.1 s: the lock lost, no wrong bit given; 20 dB */
static void fades(void)
{
    static const double len[4] = { 0.02, 0.03, 0.05, 0.1 };
    int s, l, seed, c;
    for (s = 0; s < 2; s++) {
        int bps = s ? 300 : 450;
        for (l = 0; l < 4; l++) {
            int bad = 0;
            long worst = 0;
            for (seed = 1; seed <= NSEEDS; seed++)
                for (c = 0; c < 3; c++) {
                    line_t ln;
                    run_t o;
                    memset(&ln, 0, sizeof ln);
                    ln.bps = bps; ln.hz = offs3[c]; ln.ppm = 100; ln.snr = 20; ln.all = 1;
                    ln.drop_at = 2.0; ln.drop_len = len[l];
                    ln.seed = (uint32_t)(9000 + 100 * seed + 10 * c + l + bps);
                    run_line(&ln, 1, 5.0, &o);
                    if (o.errors > worst) worst = o.errors;
                    if (l < 3 ? !(o.unlocks_drop == 0 && o.locked_end && o.errors <= 40)
                              : !(o.unlocks_drop >= 1 && o.locked_end && fabs(o.hz_err) < 1 && o.errors == 0)) bad++;
                }
            printf("fades %d: the signal off %d ms, %d lines\n", bps, (int)(len[l] * 1000 + 0.5), 3 * NSEEDS);
            if (verbose) printf("  (at most %ld wrong bits a line)\n", worst);
            bound(l < 3 ? "the lock held, at most 40 wrong bits" : "the lock lost and found again, not one wrong bit given",
                  bad == 0);
        }
    }
}

/* locked at 25 dB, then the noise up to 8 dB, and to 6 dB: no loss of
 * lock in HOLD_SECS, BER < 1e-3 */
static void hold(void)
{
    static const double lv[2] = { 8, 6 };
    int s, l;
    for (s = 0; s < 2; s++) {
        int bps = s ? 300 : 450;
        for (l = 0; l < 2; l++) {
            line_t ln;
            run_t o;
            memset(&ln, 0, sizeof ln);
            ln.bps = bps; ln.hz = 7; ln.ppm = 100; ln.snr = 25; ln.all = 1;
            ln.snr2 = lv[l]; ln.at2 = 2.0;
            ln.seed = (uint32_t)(9500 + bps + l);
            run_line(&ln, 1, 2.0 + HOLD_SECS, &o);
            printf("hold %d: %d dB for %d s\n", bps, (int)lv[l], HOLD_SECS);
            if (verbose) printf("  (%d losses of lock, %ld wrong of %ld bits)\n", o.unlocks, o.errors, o.nbits);
            bound("no loss of lock, BER < 1e-3", o.unlocks == 0 && o.locked_end && o.errors * 1000 < o.nbits);
        }
    }
}

/* grid_ok on the signal (+-7 Hz, 20 dB): 0 before the carrier's estimate,
 * and until its window of 16 decisions is full (the estimate's 8 strobes
 * decided again, its own symbol, then 6 more); 1 afterwards */
static void grid_ok(void)
{
    int s, c;
    for (s = 0; s < 2; s++) {
        int bps = s ? 300 : 450, early = 0, later = 0;
        for (c = 0; c < 2; c++) {
            static chan_t ch;
            static hst_brx_t rx;
            hst_btx_t tx;
            src_t src;
            long n = 0;
            int nsym = 0, since = -1;
            prbs_seed(0x6E1u + (uint32_t)(bps + c));
            memset(&src, 0, sizeof src);
            src.random = 1;
            hst_btx_init(&tx, bps, LEVEL, getbit, &src);
            hst_btx_preamble(&tx);
            chan_init(&ch, c ? -7 : 7, 100, LEVEL / 10.0, (uint32_t)(77 + bps + c));
            hst_brx_init(&rx, bps);
            while (n < 2 * FS) {
                int16_t y[4];
                int k, m = chan_push(&ch, hst_btx_tick(&tx), y);
                for (k = 0; k < m; k++, n++) {
                    hst_brx_tick(&rx, y[k]);
                    if (rx.nsym == nsym) continue;                   /* not a decision */
                    nsym = rx.nsym;
                    if (since < 0 && rx.acq == 2) since = 0;               /* ACQ_LOCK: the estimate made */
                    else if (since >= 0) since++;
                    if (hst_brx_grid_ok(&rx)) { if (since < 0 || since <= 6) early++; else later++; }
                }
            }
        }
        printf("grid_ok %d: 2 lines\n", bps);
        bound("0 before the estimate and for 6 decisions after it; then 1", early == 0 && later > 0);
    }
}

static void loop_450(int c) { loop_case(450, c, 0); }
static void loop_300(int c) { loop_case(300, c, 0); }

int main(int argc, char **argv)
{
    int only = t_case_arg(argc, argv, 28), c;
    verbose = getenv("HST_VERBOSE") != NULL;
    if (T_CASE(only, 1)) steps();
    if (T_CASE(only, 2)) scr17();
    if (T_CASE(only, 3)) filters();
    if (T_CASE(only, 4)) tx_phase();
    if (T_CASE(only, 5)) tx_speed();
    if (T_CASE(only, 6)) tx_spectrum();
    for (c = 0; c < 4; c++) if (T_CASE(only, 7 + c)) loop_450(c);
    for (c = 0; c < 4; c++) if (T_CASE(only, 11 + c)) loop_300(c);
    if (T_CASE(only, 15)) lock_time();
    if (T_CASE(only, 16)) cd();
    if (T_CASE(only, 17)) loop_case(450, 0, 1);
    if (T_CASE(only, 18)) loop_case(300, 0, 1);
    if (T_CASE(only, 19)) noise_first();
    if (T_CASE(only, 20)) dropout();
    if (T_CASE(only, 21)) tones();
    if (T_CASE(only, 22)) noise_locks();
    if (T_CASE(only, 23)) band();
    if (T_CASE(only, 24)) cd_level();
    if (T_CASE(only, 25)) alias();
    if (T_CASE(only, 26)) fades();
    if (T_CASE(only, 27)) hold();
    if (T_CASE(only, 28)) grid_ok();
    T_REPORT("test_hst_back");
}
